<template>
  <div v-if="isDashboard" class="contents">
    <NuxtPage />
  </div>
  <div v-else class="contents">
    <AppLoader v-if="isLoadingDetails && !userDetails" subject="user details" />
    <AppError v-else-if="detailsError" :error="detailsError" title="Failed to load user details" />
    <AppEmpty v-else-if="!userDetails" subject="user details" />
    <!-- Edit pages provide their own title + back button, so skip the details header/navbar -->
    <NuxtPage v-else-if="isEditPage" :user-details="userDetails" />
    <section v-else class="flex flex-col gap-4">
      <PageTitle :title="`${username(userDetails)} - Details`" show-doc>
        <FilterTabsNav :items="navigationItems" rounded />
      </PageTitle>
      <UserDetailsNavbar :user-id="userDetails.id" :role="userDetails.role" :chat-id="userDetails.chat_id" />
      <NuxtPage :user-details="userDetails" />
    </section>
  </div>
</template>

<script setup lang="ts">
import { getUserDetails, type GetUserDetailsResponse } from '~/client';
import type { NavigationItem } from '~/types/projects';

definePageMeta({
  roles: ['admin'],
});

const route = useRoute();
const userId = computed(() => useRoute('users-id').params?.id);

const isDashboard = computed(() => route.name === 'users-id-dashboard');
const isEditPage = computed(() => route.path.includes('/edit/'));

const {
  data: userDetails,
  error: detailsError,
  isLoading: isLoadingDetails,
} = useQuery({
  key: () => ['user', userId.value],
  query: (): Promise<GetUserDetailsResponse> =>
    getUserDetails({ composable: '$fetch', path: { user_id: userId.value } }),
  enabled: () => !!userId.value && !isDashboard.value,
});

const navigationItems = computed<NavigationItem[]>(() => {
  const items: NavigationItem[] = [
    {
      label: 'Information',
      to: { name: 'users-id', params: { id: userId.value } },
      selected: route.name === 'users-id',
    },
  ];

  if (userDetails.value?.role === 'canvasser' || userDetails.value?.role === 'subcontractor_canvasser') {
    items.push({
      label: 'Canvasser Application',
      to: { name: 'users-id-canvasser-application', params: { id: userId.value } },
      selected: route.name === 'users-id-canvasser-application',
    });
  }

  // Admins included: they are assignable to projects so they can appear in the HQ section of the
  // customer-facing Team tab. The list renders a single project column for them, as it does for
  // managers, since an admin assignment carries no pay rate or assignment status.
  items.push({
    label: 'Assignments',
    to: { name: 'users-id-assignments', params: { id: userId.value } },
    selected: route.name === 'users-id-assignments',
  });

  return items;
});

useHead({
  title: computed(() => (userDetails.value ? userDetails.value.first_name + ' ' + userDetails.value.last_name : '')),
});
</script>
